"""Expert multi-file fixtures and reference changes; generated by generate.py."""
import difflib
import json
from textwrap import dedent

def add_expert_tasks(add, write, tasks):
    def expert(id, repo, category, prompt, command, files, changes, extra=None):
        files={path:dedent(text).lstrip('\n') for path,text in files.items()}
        for path,text in files.items():
            write(f'repos/{repo}/{path}',text)
        add(id,repo,category,prompt+' Run '+command+'.',command,'.answer','','',extra)
        tasks[-1]['tags'].append('expert')
        write(f'tasks/{id}.json',json.dumps(tasks[-1],indent=2)+'\n')
        patch=''
        for path,text in changes.items():
            before=files.get(path,'')
            after=dedent(text).lstrip('\n')
            patch+=''.join(difflib.unified_diff(before.splitlines(True),after.splitlines(True),fromfile='a/'+path if before else '/dev/null',tofile='b/'+path))
        write(f'solutions/{id}.patch',patch)

